// No network calls here — Code node on n8n Cloud cannot reach the internet.
// Parses the Alpha Vantage movers response already fetched by "Get AV movers".
const data = $input.first().json;
const pool = [...(data.top_gainers || []), ...(data.most_actively_traded || [])];
const symbols = [...new Set(pool.map(x => x.ticker))].slice(0, 25);
if (!symbols.length) return [{ json: {} }];
return symbols.map(symbol => ({ json: { symbol } }));

// No network calls here — filtering only.
const MIN_GAP     = 5;    // minimum gap % vs previous close
const PRICE_MIN   = 2;
const PRICE_MAX   = 20;
const MAX_RESULTS = 10;

const items = $input.all();
const rows = [];
items.forEach((item, idx) => {
  let symbol;
  try {
    symbol = $('Extract candidates').itemMatching(idx).json.symbol;
  } catch (e) {
    return;
  }
  const q = item.json;
  if (!symbol || !q || !q.c || !q.pc) return;
  const gap = ((q.c - q.pc) / q.pc) * 100;
  if (gap >= MIN_GAP && q.c >= PRICE_MIN && q.c <= PRICE_MAX) {
    rows.push({ symbol, price: q.c, prevClose: q.pc, gap, dayHigh: q.h || 0 });
  }
});
rows.sort((a, b) => b.gap - a.gap);
const top = rows.slice(0, MAX_RESULTS);
if (!top.length) return [{ json: {} }];
return top.map(r => ({ json: r }));

// No network calls here — formatting only.
const MIN_GAP   = 5;
const PRICE_MIN = 2;
const PRICE_MAX = 20;

const newsItems = $input.all();
const firstHeadlineByIndex = {};
for (const item of newsItems) {
  const pi = item.pairedItem;
  const idx = Array.isArray(pi) ? pi[0].item : (pi ? pi.item : undefined);
  if (idx === undefined || idx in firstHeadlineByIndex) continue;
  const body = item.json;
  const headline = Array.isArray(body) ? (body[0] && body[0].headline) : body && body.headline;
  firstHeadlineByIndex[idx] = headline || null;
}

const top = $('Filter gappers').all()
  .map((item, idx) => ({ ...item.json, catalyst: firstHeadlineByIndex[idx] || '— no fresh headline —' }))
  .filter(r => r.symbol);

const dateLabel = new Date().toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' });
let html = `<h2 style="font-family:monospace">Evening debrief + after-hours \u2014 ${dateLabel}</h2>`;
html += `<div style="font-family:monospace;border:1px solid #444;padding:12px;margin-bottom:16px">
<b>Journal today's trades</b> (Commandment 04 \u2014 data is the only edge you keep):<br>
ticker \u00b7 entry \u00b7 exit \u00b7 R outcome \u00b7 what worked \u00b7 what you broke<br>
<a href="YOUR_GOOGLE_SHEET_URL">\u2192 Open trade log</a></div><h3 style="font-family:monospace">After-hours watchlist (tomorrow's levels)</h3>`;

if (!top.length) {
  html += `<p style="font-family:monospace">No qualifying gappers (gap \u2265 ${MIN_GAP}%, $${PRICE_MIN}\u2013$${PRICE_MAX}). Stay flat until a setup appears.</p>`;
} else {
  html += `<table cellpadding="8" style="border-collapse:collapse;font-family:monospace">
    <tr style="text-align:left;border-bottom:1px solid #444">
      <th>Ticker</th><th>Gap</th><th>Price</th><th>High</th><th>Catalyst</th></tr>`;
  for (const r of top) {
    html += `<tr style="border-bottom:1px solid #222">
      <td><b>${r.symbol}</b></td>
      <td style="color:#16c784">+${r.gap.toFixed(1)}%</td>
      <td>$${r.price.toFixed(2)}</td>
      <td>$${(r.dayHigh||0).toFixed(2)}</td>
      <td>${r.catalyst}</td></tr>`;
  }
  html += `</table>`;
}
html += `<p style="font-family:monospace;color:#888;margin-top:16px">Rules: catalyst required \u00b7 check float on the scanner \u00b7 mental stop before entry \u00b7 1% risk \u00b7 focus window 14:30\u201316:30 BST.</p>`;
return [{ json: { subject: `Evening debrief + after-hours \u2014 ${dateLabel}`, html } }];
